/// Generated by the separate tvbox-source-api repository and served by Pages.
/// Override at build time when deploying the generator to another account/host.
abstract final class TvBoxSourceApi {
  static const configUrl = String.fromEnvironment(
    'TVBOX_SOURCE_API_URL',
    defaultValue: 'https://amazingz-sys.github.io/tvbox-source-api/kazumi.json',
  );
  static const subscriptionName = '远端精选影视仓';
}
